<?php $pageTitle='Categories'; require_once __DIR__.'/includes/header.php'; $cats=db()->query("SELECT c.*,COUNT(b.id) blog_count FROM blog_categories c LEFT JOIN blogs b ON b.category_id=c.id GROUP BY c.id ORDER BY c.name")->fetchAll(); ?>
<div class="panel"><div class="panel-head"><div><h3>Blog Categories</h3><p>Create and organize your editorial topics.</p></div><a href="category-form.php" class="btn btn-primary"><i class="fa-solid fa-plus me-1"></i>Add Category</a></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Name</th><th>Slug</th><th>Blogs</th><th>Status</th><th class="text-end">Actions</th></tr></thead><tbody><?php foreach($cats as $c): ?><tr><td><strong><?=e($c['name'])?></strong><div class="small text-muted"><?=e($c['description'])?></div></td><td><?=e($c['slug'])?></td><td><?=$c['blog_count']?></td><td><span class="status <?=e($c['status'])?>"><?=ucfirst(e($c['status']))?></span></td><td class="text-end"><a class="icon-btn" href="category-form.php?id=<?=$c['id']?>"><i class="fa-solid fa-pen"></i></a><a class="icon-btn danger" href="category-delete.php?id=<?=$c['id']?>&csrf=<?=e(csrf_token())?>" onclick="return confirm('Delete this category? It must have 0 blogs.')"><i class="fa-solid fa-trash"></i></a></td></tr><?php endforeach;?></tbody></table></div></div>
